import asyncio

async def coro(v):
    if v == 2:
        raise ValueError('bad')
    return v

async def main():
    tasks = [asyncio.create_task(coro(i)) for i in range(1, 4)]
    try:
        results = await asyncio.gather(*tasks)
    except ValueError:
        print('caught', end=' ')
    for t in tasks:
        if not t.done():
            await t
        elif t.exception():
            print(f'err:{t.exception()}', end=' ')
        else:
            print(t.result(), end=' ')

asyncio.run(main())
